use vstd::prelude::*;

verus! {

fn swap(arr: &Vec<i32>, i: usize, j: usize) -> (result: Vec<i32>)
    requires
        i < arr.len(),
        j < arr.len(),
    ensures
        result.len() == arr.len(),
        result[i as int] == arr[j as int],
        result[j as int] == arr[i as int],
        forall|k: int|
            0 <= k < arr.len() && k != i as int && k != j as int
                ==> result[k] == arr[k],
{
    let n = arr.len();
    let mut out: Vec<i32> = Vec::with_capacity(n);

    let mut k: usize = 0;
    while k < n
        invariant
            out.len() == k,
            k <= n,
            out.len() <= n,
            forall|t: int| 0 <= t < k as int ==> {
                if t == i as int {
                    out[t] == arr[j as int]
                } else if t == j as int {
                    out[t] == arr[i as int]
                } else {
                    out[t] == arr[t]
                }
            },
        decreases n - k,
    {
        let val: i32 =
            if k == i {
                arr[j]
            } else if k == j {
                arr[i]
            } else {
                arr[k]
            };

        out.push(val);
        k = k + 1;
    }

    // After the loop, k == n and out.len() == n, so out has the right length and contents.
    out
}

} // verus!

